`timescale 1ns/1ps
// =====================================================================
//  tb_custom.v  --  directed test: Conv(3 kernels) + MaxPool 2x2 + ReLU
//  AUTO-GENERATED by golden_custom.py (edit the numbers there, not here)
//
//  Test flow:  reset -> load 3 kernels -> start -> stream 16x16 image
//              -> collect 7x7x3 outputs -> compare with golden model
// =====================================================================
module tb_custom;

    // ---------------- constants ----------------
    localparam N     = 16;          // image size
    localparam POOLN = 7;           // output size per channel
    localparam NOUT  = POOLN*POOLN; // 49 outputs per channel
    localparam SHIFT = 8;          // output quantization: ReLU, >> SHIFT, saturate

    // ---------------- DUT signals ----------------
    reg         clk = 0, rst = 1, start = 0;
    reg         k_valid = 0, pix_valid = 0;
    reg  [7:0]  k_data = 0, pix_data = 0;
    wire        out_valid, done;
    wire [23:0] out_data;           // {ch3, ch2, ch1}

    conv_pool_relu_top #(.N(N), .SHIFT(SHIFT)) dut (
        .clk(clk), .rst(rst), .start(start),
        .k_valid(k_valid), .k_data(k_data),
        .pix_valid(pix_valid), .pix_data(pix_data),
        .out_valid(out_valid), .out_data(out_data), .done(done));

    always #5 clk = ~clk;           // 100 MHz

    // ---------------- test data storage ----------------
    reg [7:0] img      [0:N*N-1];       // image, row-major
    reg [7:0] kern     [0:26];          // 3 kernels x 9 weights (two's complement)
    reg [7:0] exp_val  [0:3*NOUT-1];    // expected, index = ch*49 + r*7 + c
    reg [7:0] got_val  [0:3*NOUT-1];    // captured from the DUT

    integer i, ch, r, c;
    integer n_out  = 0;
    integer errors = 0;

    // ---------------- helper tasks to fill the data ----------------
    task set_row(input integer row,
                 input integer p0, p1, p2, p3, p4, p5, p6, p7,
                 input integer p8, p9, p10, p11, p12, p13, p14, p15);
        begin
            img[row*N+0]=p0;   img[row*N+1]=p1;   img[row*N+2]=p2;   img[row*N+3]=p3;
            img[row*N+4]=p4;   img[row*N+5]=p5;   img[row*N+6]=p6;   img[row*N+7]=p7;
            img[row*N+8]=p8;   img[row*N+9]=p9;   img[row*N+10]=p10; img[row*N+11]=p11;
            img[row*N+12]=p12; img[row*N+13]=p13; img[row*N+14]=p14; img[row*N+15]=p15;
        end
    endtask

    task set_kernel(input integer k,
                    input integer a, b, c3,
                    input integer d, e, f,
                    input integer g, h, i3);
        begin
            kern[k*9+0]=a; kern[k*9+1]=b; kern[k*9+2]=c3;
            kern[k*9+3]=d; kern[k*9+4]=e; kern[k*9+5]=f;
            kern[k*9+6]=g; kern[k*9+7]=h; kern[k*9+8]=i3;
        end
    endtask

    task set_exp(input integer chn, input integer row,
                 input integer v0, v1, v2, v3, v4, v5, v6);
        begin
            exp_val[chn*NOUT+row*POOLN+0]=v0; exp_val[chn*NOUT+row*POOLN+1]=v1;
            exp_val[chn*NOUT+row*POOLN+2]=v2; exp_val[chn*NOUT+row*POOLN+3]=v3;
            exp_val[chn*NOUT+row*POOLN+4]=v4; exp_val[chn*NOUT+row*POOLN+5]=v5;
            exp_val[chn*NOUT+row*POOLN+6]=v6;
        end
    endtask

    // ---------------- stimulus tasks ----------------
    task do_reset;
        begin
            rst <= 1;
            repeat (4) @(posedge clk);
            rst <= 0;
            @(posedge clk);
        end
    endtask

    task load_kernels;                 // 27 bytes: kernel1, kernel2, kernel3
        integer k;
        begin
            for (k = 0; k < 27; k = k + 1) begin
                @(posedge clk);
                k_valid <= 1;  k_data <= kern[k];
            end
            @(posedge clk);  k_valid <= 0;
        end
    endtask

    task pulse_start;
        begin
            @(posedge clk);  start <= 1;
            @(posedge clk);  start <= 0;
        end
    endtask

    task stream_image;                 // one pixel per clock, row-major
        integer p;
        begin
            for (p = 0; p < N*N; p = p + 1) begin
                @(posedge clk);
                pix_valid <= 1;  pix_data <= img[p];
            end
            @(posedge clk);  pix_valid <= 0;
        end
    endtask

    // ---------------- output monitor ----------------
    // Every cycle with out_valid=1 delivers one pooled position for all 3 channels.
    always @(posedge clk) begin
        if (out_valid) begin
            if (n_out >= NOUT) begin
                $display("ERROR: more than %0d outputs", NOUT);
                errors = errors + 1;
            end else begin
                got_val[0*NOUT+n_out] = out_data[7:0];
                got_val[1*NOUT+n_out] = out_data[15:8];
                got_val[2*NOUT+n_out] = out_data[23:16];
                for (ch = 0; ch < 3; ch = ch + 1)
                    if (got_val[ch*NOUT+n_out] !== exp_val[ch*NOUT+n_out]) begin
                        $display("MISMATCH ch%0d (r=%0d,c=%0d): got %0d, expected %0d",
                                 ch+1, n_out/POOLN, n_out%POOLN,
                                 got_val[ch*NOUT+n_out], exp_val[ch*NOUT+n_out]);
                        errors = errors + 1;
                    end
            end
            n_out = n_out + 1;
        end
    end

    // ---------------- result printing ----------------
    task print_grids;
        begin
            for (ch = 0; ch < 3; ch = ch + 1) begin
                $display("\nChannel %0d   (DUT output | expected)", ch+1);
                for (r = 0; r < POOLN; r = r + 1) begin
                    $write("  ");
                    for (c = 0; c < POOLN; c = c + 1) $write("%3d ", got_val[ch*NOUT+r*POOLN+c]);
                    $write("   |   ");
                    for (c = 0; c < POOLN; c = c + 1) $write("%3d ", exp_val[ch*NOUT+r*POOLN+c]);
                    $write("\n");
                end
            end
        end
    endtask

    // ---------------- timeout guard ----------------
    initial begin
        #1_000_000;
        $display("TIMEOUT: done never asserted");
        $finish;
    end

    // =================================================================
    //  TEST DATA  (generated from the golden model)
    // =================================================================
    task fill_test_data;
        begin
            // ---- input image 16x16 ----
            set_row( 0, 170, 249,  18, 218,   4, 172, 206,  45, 191,  76, 195,   6, 103,  89, 209, 163);
            set_row( 1, 234, 241, 143,  93, 229, 230, 158, 119, 115, 156, 111,  20,  95,  31, 217,  94);
            set_row( 2,  26,  54, 185, 164, 199, 220, 219,  90,  40, 107, 192, 212,  92, 103,  95, 202);
            set_row( 3,  92,  91,  85, 180, 168, 129, 183, 231,  23,  32, 161, 184, 206,   4, 103,  45);
            set_row( 4,  79, 179, 195, 219, 162, 231,  28, 167,  13,  29,  53,  25, 246, 145,  93,  76);
            set_row( 5,  49, 148, 105,  42, 178, 213, 138, 247, 113, 150,  91, 186, 212,  76, 123, 235);
            set_row( 6,  24, 221,  81,  72, 212, 109, 200, 162,   0,  41, 171, 154, 251,  12, 179, 192);
            set_row( 7,  97,  80,  54,  30, 214,  28, 225, 131,  53, 201,   0, 165,  36, 223, 109, 211);
            set_row( 8,  20,  73, 245, 167,  66,  17, 201, 114,  27,  94, 203, 117, 182, 105, 188,  86);
            set_row( 9,  13, 219,  64,  40,  42, 103,  36,  71, 151, 151, 104,  37, 149, 246, 240,  57);
            set_row(10, 218, 119, 146, 218, 193, 238, 155, 134, 118,  34, 115,  23, 184,  64,  80, 110);
            set_row(11,  26,  51,  82,  69, 132,  52, 198, 169, 115, 127, 142, 212, 139, 131,  73,   3);
            set_row(12,  65, 222,  63, 119, 129, 151, 156, 114, 187, 150, 158, 253,  45, 125, 124,  93);
            set_row(13,  88, 199,  75,  42, 189, 147,   5,  50, 162, 214,  64, 122,  53,  33,  73, 152);
            set_row(14, 233, 217, 153,  83, 216, 174, 112, 111,   6, 184, 204, 169,  65,  62, 204,  76);
            set_row(15, 156, 215, 248, 246, 127,  75, 156,  53,  91,  50, 108, 239, 185,  92, 231, 223);

            // ---- kernel 1 ----
            set_kernel(0,  -28, -111,  125,
                           116,    4,   -3,
                           -90,   76,    7);
            // ---- kernel 2 ----
            set_kernel(1, -100,  -38,    7,
                           -53,  -45,  -47,
                            27,  -64,  122);
            // ---- kernel 3 ----
            set_kernel(2,  105,  -76,  115,
                             2,  -40,  -40,
                            59,   60,   16);

            // ---- expected output, channel 1 (after conv, maxpool, ReLU, >> SHIFT, saturate) ----
            set_exp(0, 0, 222, 168, 132,  92, 117, 118,  94);
            set_exp(0, 1, 136, 113,  96,  82,  75, 141,  90);
            set_exp(0, 2,  91, 110, 165,  46,  93, 139, 172);
            set_exp(0, 3,  64, 188, 118, 135, 116, 167, 136);
            set_exp(0, 4,  74, 143, 161,  93,  96, 112,  69);
            set_exp(0, 5,  77,  60,  96,  82,  95, 154,  80);
            set_exp(0, 6,  70, 123, 106,  86, 135,  98, 111);
            // ---- expected output, channel 2 (after conv, maxpool, ReLU, >> SHIFT, saturate) ----
            set_exp(1, 0,   0,   0,   0,   0,   0,   6,   0);
            set_exp(1, 1,   0,   0,   0,   0,  30,   0,  13);
            set_exp(1, 2,   0,   0,   0,   0,   0,   0,   0);
            set_exp(1, 3,  16,   0,   0,   0,  28,   0,   0);
            set_exp(1, 4,   0,   0,   0,   0,   0,   0,   0);
            set_exp(1, 5,   0,   0,   0,   0,   0,   0,   0);
            set_exp(1, 6,   0,   1,   0,   0,   0,   0,  25);
            // ---- expected output, channel 3 (after conv, maxpool, ReLU, >> SHIFT, saturate) ----
            set_exp(2, 0, 225, 192, 141, 195, 148, 207, 151);
            set_exp(2, 1, 123, 169, 173, 189, 126, 147, 168);
            set_exp(2, 2, 166, 157, 185, 185, 124, 154, 159);
            set_exp(2, 3, 171, 169, 183, 171, 168, 191, 228);
            set_exp(2, 4, 139, 165, 200, 115, 106, 158, 142);
            set_exp(2, 5, 170, 177, 159, 108, 136, 167, 109);
            set_exp(2, 6, 200, 180, 153, 133, 201, 192, 106);
        end
    endtask

    // =================================================================
    //  MAIN TEST SEQUENCE
    // =================================================================
    initial begin
        $dumpfile("tb_custom.vcd");
        $dumpvars(0, tb_custom);

        fill_test_data;
        do_reset;                    // 1. reset
        load_kernels;                // 2. load the 3 kernels
        pulse_start;                 // 3. start
        stream_image;                // 4. send the 256 pixels
        wait (done);                 // 5. wait for the DUT to finish
        repeat (3) @(posedge clk);

        print_grids;                 // 6. show results

        if (n_out != NOUT) begin
            $display("ERROR: got %0d outputs, expected %0d", n_out, NOUT);
            errors = errors + 1;
        end
        if (errors == 0) $display("\nPASS: all %0d x 3 outputs match the golden model", NOUT);
        else             $display("\nFAIL: %0d errors", errors);
        $finish;
    end
endmodule
